import { useContext } from "react";
import { CartContext } from "../../context/cart.context";
import CheckoutItem from "../../components/checkout-item/checkout-item.component";
import {
    CheckoutContainer,
    CheckoutHeader,
    HeaderBlock,
    Total,
    EmptyCartMessage,
    CartIconWithCount,
    StyledShoppingIcon,
    CartCount
} from './checkout.styles';

const Checkout = () => {
    const { cartItems, cartTotal, cartCount } = useContext(CartContext);
    const headerBlockElements = ['Product', 'Description', 'Quantity', 'Price', 'Remove'];

    return (
        <CheckoutContainer>
            {cartItems.length ? (
                <div>
                    <CheckoutHeader>
                        {headerBlockElements.map((header, index) => (
                            <HeaderBlock key={index}>{header}</HeaderBlock>
                        ))}
                    </CheckoutHeader>
                    {cartItems.map((cartItem) => (
                        <CheckoutItem key={cartItem.id} cartItemProp={cartItem} />
                    ))}
                    <Total>Total: €{cartTotal}</Total>
                </div>
            ) : (
                <EmptyCartMessage>
                    <CartIconWithCount>
                        <StyledShoppingIcon />
                        <CartCount>{cartCount}</CartCount>
                    </CartIconWithCount>
                    <h2>Your cart is empty</h2>
                </EmptyCartMessage>
            )}
        </CheckoutContainer>
    );
};

export default Checkout;
